import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const root = fileURLToPath(new URL('../', import.meta.url))
const result = await build({
  absWorkingDir: root, entryPoints: ['src/client/index.js'],
  bundle: true, format: 'cjs', platform: 'browser', target: 'es2022',
  external: ['react', 'react-dom'], loader: { '.css': 'text' },
  minify: true, charset: 'utf8', legalComments: 'inline', write: false,
})
const output = [
  '// Generated by npm run build. Do not edit.',
  'window.__ModuleLoader__.load({ id: "dsh-bothub", factory: (require) => {',
  'const module = { exports: {} };',
  result.outputFiles[0].text,
  'return Object.defineProperty({ ...module.exports }, Symbol.toStringTag, { value: "Module" });',
  '} });', '',
].join('\n')
const path = new URL('../client.js', import.meta.url)
if (process.argv.includes('--check')) {
  const current = await readFile(path, 'utf8').catch(() => '')
  if (current !== output) {
    console.error('client.js is stale: run npm run build in dsh-bothub.')
    process.exitCode = 1
  }
} else await writeFile(path, output)
